"use client";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Command as Primitive } from "cmdk";
import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogDescription,
  type DialogProps,
} from "@/components/ui/dialog";
import { useFlowGroup } from "@/lib/sahajiv-motion/use-flow";
import { Icon } from "@/components/ui/icon";
export const commandVariants = cva(
  "v-cmd [background:var(--popover)] [width:min(520px,100%)] [overflow:hidden] [border:0] [box-shadow:var(--shadow-float),inset_0_0_0_1px_var(--v-border)] [border-radius:22px]",
);
export type CommandProps = React.ComponentProps<typeof Primitive>;
export function Command({ className, ref, ...props }: CommandProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  return (
    <Primitive
      ref={morphRef}
      data-slot="command"
      data-part="root"
      data-command=""
      className={cn(commandVariants(), className)}
      {...props}
    />
  );
}
export type CommandDialogProps = DialogProps & {
  title?: string;
  description?: string;
  className?: string;
};
export function CommandDialog({
  children,
  title = "Command palette",
  description = "Search for a command to run.",
  className,
  ...props
}: CommandDialogProps) {
  return (
    <Dialog {...props}>
      <DialogContent className="p-0">
        <DialogTitle className="sr-only">{title}</DialogTitle>
        <DialogDescription className="sr-only">{description}</DialogDescription>
        <Command className={className}>{children}</Command>
      </DialogContent>
    </Dialog>
  );
}
export type CommandInputProps = React.ComponentProps<typeof Primitive.Input> & {
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
};
export function CommandInput({
  className,
  leading,
  trailing,
  ...props
}: CommandInputProps) {
  const wrapperRef = useMorph<HTMLDivElement>("inputs");
  return (
    <div
      ref={wrapperRef}
      data-slot="command-input-wrapper"
      className="v-cmd__input"
    >
      {leading ?? <Icon name="search" />}
      <Primitive.Input
        data-slot="command-input"
        data-part="trigger"
        className={cn(
          "min-w-0 flex-1 bg-transparent [border:0] [outline:0] [padding:1px_2px] text-[length:var(--fs-body)]",
          className,
        )}
        {...props}
      />
      {trailing}
    </div>
  );
}
export type CommandListProps = React.ComponentProps<typeof Primitive.List>;
export function CommandList({ className, ref, ...props }: CommandListProps) {
  const groupRef = useFlowGroup<HTMLDivElement>(ref, {
    itemSelector: ".v-menu__item",
    activeSelector: "[aria-selected=true]",
  });
  return (
    <Primitive.List
      ref={groupRef}
      data-slot="command-list"
      data-part="content"
      className={cn("v-cmd__list", className)}
      {...props}
    />
  );
}
export type CommandEmptyProps = React.ComponentProps<typeof Primitive.Empty>;
export function CommandEmpty({ className, ...props }: CommandEmptyProps) {
  return (
    <Primitive.Empty
      data-slot="command-empty"
      data-part="empty"
      className={cn("v-cmd__empty", className)}
      {...props}
    />
  );
}
export type CommandGroupProps = React.ComponentProps<typeof Primitive.Group>;
export function CommandGroup({ className, ...props }: CommandGroupProps) {
  return (
    <Primitive.Group
      data-slot="command-group"
      data-part="group"
      className={className}
      {...props}
    />
  );
}
export type CommandItemProps = React.ComponentProps<typeof Primitive.Item> & {
  variant?: "default" | "danger";
};
export function CommandItem({
  className,
  variant,
  ref,
  ...props
}: CommandItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="command-item"
      data-part="item"
      className={cn(
        "v-menu__item",
        variant === "danger" && "-danger",
        className,
      )}
      {...props}
    />
  );
}
export type CommandSeparatorProps = React.ComponentProps<
  typeof Primitive.Separator
>;
export function CommandSeparator({
  className,
  ...props
}: CommandSeparatorProps) {
  return (
    <Primitive.Separator
      data-slot="command-separator"
      data-part="separator"
      className={cn("v-menu__sep", className)}
      {...props}
    />
  );
}
export type CommandShortcutProps = React.ComponentProps<"span">;
export function CommandShortcut({ className, ...props }: CommandShortcutProps) {
  return (
    <span
      data-slot="command-shortcut"
      className={cn("v-kbd ml-auto", className)}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu:where([data-slot="command"], [data-slot^="command-"]) {
  background: var(--popover);
  border-radius: var(--r-card-sm);
  padding: var(--s-2);
  min-width: 200px;
  box-shadow: var(--shadow-float);
  border: 1px solid var(--v-border);
  display: grid;
  gap: 2px;
}
.v-menu__item:where([data-slot="command"], [data-slot^="command-"]) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where([data-slot="command"], [data-slot^="command-"]):hover,
.v-menu__item:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )[aria-selected="true"] {
  background: var(--v-beige);
}
.v-menu__item:where([data-slot="command"], [data-slot^="command-"]).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="command"], [data-slot^="command-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  height: 52px;
  padding: 0 var(--s-5);
  border-bottom: 1px solid var(--v-border);
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) input {
  flex: 1;
  background: none;
  border: 0;
  outline: 0;
  font-size: var(--fs-body);
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]) {
  max-height: 320px;
  overflow: auto;
  padding: var(--s-2);
}
.v-cmd__empty:where([data-slot="command"], [data-slot^="command-"]) {
  padding: var(--s-6);
  text-align: center;
  color: var(--muted-foreground);
  font-size: var(--fs-control);
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) {
  box-shadow: inset 0 0 0 1px var(--v-edge);
}
.v-cmd__input:where(
    [data-slot="command"],
    [data-slot^="command-"]
  ):focus-within {
  box-shadow: inset 0 0 0 2px var(--v-brand);
  border-color: transparent;
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) {
  box-shadow: none;
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) {
  height: 56px;
  padding: 0 14px 0 18px;
  gap: 12px;
  border-bottom: 1px solid var(--v-border);
  background: var(--v-canvas);
  box-shadow: none;
  color: var(--v-text);
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) > .v-icon {
  width: 20px;
  height: 20px;
  color: var(--v-text-2);
}
.v-cmd__input:where(
    [data-slot="command"],
    [data-slot^="command-"]
  ):focus-within {
  box-shadow: none;
  background: color-mix(in oklab, var(--v-pink) 10%, var(--v-canvas));
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]):focus-within
  > .v-icon {
  color: var(--v-text);
}
.v-cmd__input:where([data-slot="command"], [data-slot^="command-"]) .v-kbd {
  background: var(--v-beige);
  border-bottom-color: var(--v-edge);
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]) {
  padding: 8px;
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  [cmdk-group-heading] {
  padding: 10px 12px 6px;
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]),
.v-menu:where([data-slot="command"], [data-slot^="command-"]) {
  scrollbar-gutter: stable;
}
.v-cmd__list:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar,
.v-menu:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-cmd__list:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar-track,
.v-menu:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-cmd__list:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar-thumb,
.v-menu:where(
    [data-slot="command"],
    [data-slot^="command-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"]) .v-menu__item {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  min-height: 44px;
  padding: 0 10px 0 8px;
  border-radius: 12px;
  font-size: 14.5px;
  transition: background var(--t-micro);
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item
  .v-disk {
  width: 28px;
  height: 28px;
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item
  .v-disk
  .v-icon {
  width: 15px;
  height: 15px;
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item:hover {
  background: color-mix(in oklab, var(--v-beige) 70%, var(--v-canvas));
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item[aria-selected="true"] {
  background: var(--v-pink-soft);
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-pink);
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item[aria-selected="true"]::after {
  content: "\21B5";
  font-size: 12px;
  font-weight: 600;
  color: var(--v-text-2);
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: var(--v-canvas);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item.-danger[aria-selected="true"] {
  background: var(--status-danger-bg);
  box-shadow: inset 0 0 0 1px var(--v-danger);
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  [cmdk-group-heading] {
  padding: 12px 12px 6px;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  color: var(--v-text-2);
}
.v-cmd:where([data-slot="command"], [data-slot^="command-"])
  [cmdk-group-heading]
  + .v-menu__item {
  margin-top: 0;
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]) {
  padding: 6px 8px 10px;
  display: grid;
  gap: 2px;
}
.v-cmd__empty:where([data-slot="command"], [data-slot^="command-"]) {
  padding: 28px 20px;
  font-size: 14px;
  color: var(--v-text-2);
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]),
.v-menu:where([data-slot="command"], [data-slot^="command-"]) {
  scrollbar-gutter: stable;
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]) {
  scrollbar-gutter: stable;
}
.v-cmd__list:where([data-slot="command"], [data-slot^="command-"]),
.v-menu:where([data-slot="command"], [data-slot^="command-"]) {
  scrollbar-gutter: stable;
}
:root[data-mode="dark"]
  .v-cmd__input:where([data-slot="command"], [data-slot^="command-"]),
:root[data-mode="dark"]
  .v-cmd:where([data-slot="command"], [data-slot^="command-"]) {
  background: var(--v-beige);
}
:root[data-mode="dark"]
  .v-cmd:where([data-slot="command"], [data-slot^="command-"])
  .v-menu__item[aria-selected="true"]::after {
  background: var(--v-beige-2);
  color: var(--v-text);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="command"],
  [data-slot^="command-"],
  [data-slot="command"]::before,
  [data-slot="command"]::after,
  [data-slot^="command-"]::before,
  [data-slot^="command-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="command-list"] > [cmdk-list-sizer],
[data-slot="command-list"] [cmdk-group],
[data-slot="command-list"] [cmdk-group-items] {
  display: contents;
}
[data-slot="command-group"] [cmdk-group-heading] {
  padding: 12px 12px 6px;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--v-text-2);
}
[data-slot="command-group"][hidden] {
  display: none;
}
[data-slot="command-item"][data-disabled="true"] {
  pointer-events: none;
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot="command-item"] {
  cursor: pointer;
}

/* cmdk keeps its semantic group wrappers; items still paint above the shared selection layer. */
[data-flow-owned][data-slot="command-list"] [data-slot="command-item"] {
  position: relative;
  z-index: 1;
}

}
